import logging
import six

from pathlib import Path
from typing import Union, Optional

from taf.transport.ssh import ssh

from taf.rfrl.csv4all.resources.utilities.exceptions import FunctionTimeoutException
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger, wait_until_success

logging.getLogger('taf.transport.ssh').setLevel(logging.ERROR)


class NodeSSHManager:

    def __init__(self, node_alias, vm_dict=None, bts_host_ip: str = "192.168.255.129",
                 node_ssh_username: str = "toor4nsn", node_ssh_password: str = "oZPS0POrRieRtu"):
        self.node_alias = node_alias
        self.vm_dict = vm_dict
        self.bts_host_ip = bts_host_ip
        self.node_ssh_username = node_ssh_username
        self.node_ssh_password = node_ssh_password
        self.master_smod = self.SSHContextManager(self.node_alias, self.vm_dict, self.bts_host_ip, node_ssh_username,
                                                  node_ssh_password)
        self.slave_smod = self.set_slave_smod_manager_if_fullrack()

    class SSHContextManager(ssh):
        def __init__(self, node_alias, vm_dict, bts_host_ip, node_ssh_username, node_ssh_password,
                     slave_smod_hostname=None):
            super().__init__()
            self.node_alias = node_alias
            self.vm_dict = vm_dict
            self.slave_smod_hostname = slave_smod_hostname
            self.bts_host_ip = bts_host_ip
            self.node_ssh_username = node_ssh_username
            self.node_ssh_password = node_ssh_password
            self.ssh_client: ssh = None
            self.alias = f"{'master' if not slave_smod_hostname else 'slave'}_smod_{self.node_alias}"

        def __enter__(self):
            try:
                wait_until_success(60, 10, self.__setup_connection)
                return self
            except FunctionTimeoutException:
                test_logger(f"Unable to connect to {self.bts_host_ip}", "ERROR")
                raise

        def __exit__(self, exc_type, exc_val, exc_tb):
            if self.ssh_client:
                logging.debug(f"Closing connection for {self.node_alias}")
                self.ssh_client.disconnect(connection=self.connection)

        def __setup_connection(self):
            self.ssh_client = ssh()
            vm_proxy = self.ssh_client.connect_to(hostname=self.vm_dict.get('host'),
                                                  username=self.vm_dict.get('user'),
                                                  password=self.vm_dict.get('password')) if self.vm_dict else None
            self.connection = self.ssh_client.connect_to(hostname=self.bts_host_ip,
                                                         username=self.node_ssh_username,
                                                         password=self.node_ssh_password,
                                                         proxy=vm_proxy,
                                                         alias=f"master_smod_{self.node_alias}")
            if self.slave_smod_hostname:
                self.connection = self.ssh_client.connect_to(hostname=self.slave_smod_hostname,
                                                             username=self.node_ssh_username,
                                                             password=self.node_ssh_password,
                                                             proxy=self.connection,
                                                             alias=f"slave_smod_{self.node_alias}")

    def set_slave_smod_manager_if_fullrack(self) -> Union[None, SSHContextManager]:
        secondary_smod_ip = ''
        with self.master_smod as ssh_manager:
            hostname = six.ensure_text(ssh_manager.execute("hostname", connection=ssh_manager.connection)).strip()
            if hostname == "fct-0a":
                check_secondary_smod = r"""cat /etc/hosts | grep 'fct-4a' | awk '{print $3}'"""
                secondary_smod_ip = six.ensure_text(ssh_manager.execute(check_secondary_smod,
                                                                        connection=ssh_manager.connection)).rstrip()
            elif hostname == "fct-4a":
                check_secondary_smod = r"""cat /etc/hosts | grep 'fct-0a' | awk '{print $3}'"""
                secondary_smod_ip = six.ensure_text(ssh_manager.execute(check_secondary_smod,
                                                                        connection=ssh_manager.connection)).rstrip()
            if not secondary_smod_ip:
                check_secondary_smod = r"""netstat -rn | grep '192.168.255.7' | awk '{print $2}'"""
                secondary_smod_ip = six.ensure_text(ssh_manager.execute(check_secondary_smod,
                                                                        connection=ssh_manager.connection)).rstrip()
        if secondary_smod_ip:
            return self.SSHContextManager(self.node_alias, self.vm_dict, self.bts_host_ip, self.node_ssh_username,
                                          self.node_ssh_password, secondary_smod_ip)

    def get_file_from_bts(self, bts_file_path, target_dir, file_name, slave_smod=False):
        smod = self.slave_smod if slave_smod else self.master_smod
        local_file_path = f"{target_dir}/{file_name}"
        if not Path(target_dir).exists():
            Path(target_dir).mkdir(parents=True)
        with smod as ssh_manager:
            if ssh_manager.file_exists(bts_file_path, connection=ssh_manager.connection):
                ssh_manager.download_file(bts_file_path, local_file_path, connection=ssh_manager.connection)
            else:
                test_logger(f"File doesn't exist: {bts_file_path} on {smod.alias}", "ERROR")
                raise FileNotFoundError(f"File doesn't exist: {bts_file_path}")
        return local_file_path

    def upload_file_to_bts(self, local_file_path, bts_file_path, slave_smod=False):
        smod = self.slave_smod if slave_smod else self.master_smod
        if Path(local_file_path).exists():
            with smod as ssh_manager:
                ssh_manager.upload_file(local_file_path, bts_file_path, connection=ssh_manager.connection)

    def execute_command(self, cmd: str, timeout: Union[str, None] = None, slave_smod: Optional[bool] = False) -> str:
        smod = self.slave_smod if slave_smod else self.master_smod
        with smod as ssh_manager:
            return ssh_manager.execute(cmd, connection=ssh_manager.connection, timeout=timeout)

    def file_exists(self, file_name: str, timeout: Union[str, None] = None, slave_smod: Optional[bool] = False) -> str:
        smod = self.slave_smod if slave_smod else self.master_smod
        with smod as ssh_manager:
            return ssh_manager.file_exists(file_name, connection=ssh_manager.connection, timeout=timeout)

    def is_slave_smod(self):
        if self.slave_smod:
            return True
        return False

    def get_module_type(self, slave: Optional[bool] = False):
        command = r"""timeout 5m sysinfo 2>&1| head -n10 | grep "ID_00_MODULE_ID_\[0\]" | awk -F "'" '{print $2}'"""
        return self.execute_command(command, slave_smod=slave).rstrip()
